CREATE DATABASE IF NOT EXISTS garage CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE garage;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS job_photos,notifications,payments,invoice_items,invoices,stock_movements,job_parts,job_status_history,repair_jobs,parts,suppliers,vehicles,auth_tokens,password_resets,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30),password_hash VARCHAR(255) NOT NULL,role ENUM('admin','mechanic','customer') NOT NULL DEFAULT 'customer',status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(role,status));
CREATE TABLE auth_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(expires_at));
CREATE TABLE password_resets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE vehicles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,registration_no VARCHAR(30) NOT NULL UNIQUE,make VARCHAR(80) NOT NULL,model VARCHAR(80),year SMALLINT,vin VARCHAR(80),mileage INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES users(id),INDEX(customer_id));
CREATE TABLE suppliers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,phone VARCHAR(30),email VARCHAR(190),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE parts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,description TEXT,quantity INT NOT NULL DEFAULT 0,reorder_level INT NOT NULL DEFAULT 5,buying_price DECIMAL(12,2) NOT NULL DEFAULT 0,selling_price DECIMAL(12,2) NOT NULL DEFAULT 0,supplier_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL,INDEX(quantity));
CREATE TABLE repair_jobs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,vehicle_id BIGINT UNSIGNED NOT NULL,mechanic_id BIGINT UNSIGNED NULL,title VARCHAR(180) NOT NULL,description TEXT,diagnosis TEXT,work_performed TEXT,notes TEXT,status ENUM('assigned','diagnosing','in_progress','waiting_parts','ready_inspection','completed','cancelled') NOT NULL DEFAULT 'assigned',estimated_cost DECIMAL(12,2) DEFAULT 0,labour_cost DECIMAL(12,2) DEFAULT 0,final_cost DECIMAL(12,2) DEFAULT 0,estimated_completion DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(vehicle_id) REFERENCES vehicles(id),FOREIGN KEY(mechanic_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(status,mechanic_id));
CREATE TABLE job_status_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_id BIGINT UNSIGNED NOT NULL,status VARCHAR(40) NOT NULL,note TEXT,changed_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(job_id) REFERENCES repair_jobs(id) ON DELETE CASCADE,FOREIGN KEY(changed_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE job_parts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_id BIGINT UNSIGNED NOT NULL,part_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(12,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(job_id) REFERENCES repair_jobs(id) ON DELETE CASCADE,FOREIGN KEY(part_id) REFERENCES parts(id));
CREATE TABLE stock_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,part_id BIGINT UNSIGNED NOT NULL,type ENUM('in','out','adjustment') NOT NULL,quantity INT NOT NULL,reference_type VARCHAR(40),reference_id BIGINT UNSIGNED NULL,notes TEXT,user_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(part_id) REFERENCES parts(id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,job_id BIGINT UNSIGNED NOT NULL,invoice_no VARCHAR(60) NOT NULL UNIQUE,subtotal DECIMAL(12,2) NOT NULL DEFAULT 0,tax DECIMAL(12,2) NOT NULL DEFAULT 0,total DECIMAL(12,2) NOT NULL DEFAULT 0,status ENUM('unpaid','partial','paid','cancelled') NOT NULL DEFAULT 'unpaid',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(job_id) REFERENCES repair_jobs(id));
CREATE TABLE invoice_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,description VARCHAR(255) NOT NULL,quantity DECIMAL(12,2) NOT NULL,unit_price DECIMAL(12,2) NOT NULL,line_total DECIMAL(12,2) NOT NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE);
CREATE TABLE payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,method ENUM('mpesa','cash','card','other') NOT NULL,amount DECIMAL(12,2) NOT NULL,transaction_ref VARCHAR(100),phone VARCHAR(30),status ENUM('pending','successful','failed') NOT NULL DEFAULT 'pending',raw_response JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(invoice_id) REFERENCES invoices(id),INDEX(status,transaction_ref));
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,body TEXT NOT NULL,type VARCHAR(40),reference_id BIGINT UNSIGNED NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id,read_at));
CREATE TABLE job_photos(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,path VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(job_id) REFERENCES repair_jobs(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id));
